    INCUBATION_TIME = '[[INCUBATION_TIME]]'
    INCUBATION_TEMPERATURE = '[[INCUBATION_TEMPERATURE]]'
    SHAKER_SPEED_INCUBATION = '[[SHAKER_SPEED_INCUBATION]]'

